import os, re

def load_all_grids():
    """Load all grids shown in this session."""
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        # Try to find from env
        for k, v in os.environ.items():
            if 'SESSION' in k.upper() or 'DIR' in k.upper():
                print(f"Env: {k}={v}")
        return {}

    # Figure out the session file path
    import json
    session_file = os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl')
    print(f"Session file: {session_file}")

    if os.path.exists(session_file):
        with open(session_file) as f:
            content = f.read()
        print(f"File size: {len(content)} bytes")
        # Find demo pairs
        demos = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content)
        result = {}
        for m in demos:
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in content[m.end():].split('\n')[:h]]
            if k not in result and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                result[k] = [[int(x) for x in r] for r in rows]
        return result
    return {}

